"""Plot daily Kp versus orbital decay for the 2017–2019 satellite sample.Requires numpy, pandas, matplotlib, scipy (included in most Anaconda installs).Positive decay means altitude loss. No outliers or altitude gains are removed.Kp is matched to the ending date of each consecutive-day altitude difference."""from pathlib import Pathimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom scipy.stats import pearsonr, linregressPROJECT_DIR = Path('/Users/carmencardenas/Documents/GitHub/Space_Weather_Risks')FILE_PATH = PROJECT_DIR / 'data/processed/daily_satellite_altitude_kp.csv'OUTPUT_DIR = PROJECT_DIR / 'results'SATELLITES = [27651, 33591, 39444]# Set an exact column name here only if automatic detection cannot find it.COLUMN_OVERRIDES = {'date': None, 'id': None, 'altitude': None, 'kp': None}ALIASES = {    'date': ['date', 'day', 'epoch', 'datetime'],    'id': ['norad_id', 'norad_cat_id', 'satellite_id', 'norad'],    'altitude': ['altitude_km', 'daily_median_altitude_km', 'median_altitude_km',                 'mean_altitude_km', 'daily_mean_altitude_km', 'altitude'],    'kp': ['daily_max_kp', 'max_daily_kp', 'kp_daily_max', 'kp_max', 'kp']}def main():    if not FILE_PATH.is_file():        candidates = sorted((PROJECT_DIR / 'data').rglob('*.csv'))        listing = '\n'.join(str(p) for p in candidates)        raise FileNotFoundError(            f'Merged satellite file not found:\n{FILE_PATH}\n\n'            f'Available CSV files:\n{listing}\n\n'            'Set FILE_PATH to the 2017–2019 merged satellite altitude + Kp file. '            'The Kp-only file and Starlink 2022 file are not suitable here.'        )    df = pd.read_csv(FILE_PATH)    print('Loaded:', FILE_PATH)    print('Columns:', df.columns.tolist())    lookup = {str(c).strip().lower(): c for c in df.columns}    columns = {}    for key, aliases in ALIASES.items():        override = COLUMN_OVERRIDES[key]        name = override if override is not None else next(            (lookup[a] for a in aliases if a in lookup), None)        if name not in df.columns:            raise ValueError(                f'Cannot identify the {key} column. Available: {df.columns.tolist()}. '                f'Set COLUMN_OVERRIDES["{key}"] to its exact name. '                'Altitude must be in kilometers.'            )        columns[key] = name    print('Using columns:', columns)    data = pd.DataFrame({        'date': pd.to_datetime(df[columns['date']], utc=True, errors='coerce').dt.normalize(),        'norad_id': pd.to_numeric(df[columns['id']], errors='coerce'),        'altitude_km': pd.to_numeric(df[columns['altitude']], errors='coerce'),        'kp': pd.to_numeric(df[columns['kp']], errors='coerce')    }).replace([np.inf, -np.inf], np.nan)    data = data.dropna(subset=['date', 'norad_id', 'altitude_km'])    data = data[data.norad_id.isin(SATELLITES)].copy()    missing = sorted(set(SATELLITES) - set(data.norad_id))    if missing:        raise ValueError(f'Missing satellite IDs: {missing}. Use the 2017–2019 dataset.')    if data.duplicated(['norad_id', 'date']).any():        raise ValueError('Multiple rows per satellite per day. Use the daily dataset.')    data = data.sort_values(['norad_id', 'date'])    groups = data.groupby('norad_id')    data['days_between'] = groups['date'].diff().dt.total_seconds() / 86400    data['decay_m_day'] = -1000 * groups['altitude_km'].diff() / data.days_between    data = data[data.days_between.eq(1)].dropna(subset=['kp', 'decay_m_day'])    if not data.kp.between(0, 9).all():        raise ValueError('Kp values must be between 0 and 9. Check the selected column.')    plt.rcParams.update({'font.size': 13, 'axes.titlesize': 16,                         'axes.labelsize': 14, 'font.family': 'DejaVu Sans'})    fig, axes = plt.subplots(1, 3, figsize=(16, 5.8), sharex=True,                             sharey=True, constrained_layout=True)    results = []    for ax, satellite in zip(axes, SATELLITES):        subset = data[data.norad_id.eq(satellite)]        x, y = subset.kp.to_numpy(), subset.decay_m_day.to_numpy()        if len(x) < 3 or np.unique(x).size < 2 or np.unique(y).size < 2:            raise ValueError(f'Insufficient variable data for NORAD {satellite}.')        r, p = pearsonr(x, y)        fit = linregress(x, y)        ax.scatter(x, y, s=28, alpha=.5, color='#247BA0', edgecolors='none')        line_x = np.linspace(x.min(), x.max(), 100)        ax.plot(line_x, fit.intercept + fit.slope * line_x,                color='#C44E52', linewidth=2.3)        ax.axhline(0, color='gray', linestyle=':', linewidth=1)        ax.set_title(f'NORAD {satellite}')        ax.set_xlabel('Daily maximum Kp')        ax.grid(alpha=.2)        ax.set_axisbelow(True)        ax.text(.04, .96, f'r = {r:.3f}\np = {p:.2e}\nn = {len(x)}',                transform=ax.transAxes, va='top', fontsize=12,                bbox=dict(facecolor='white', edgecolor='none', alpha=.85))        results.append(dict(norad_id=satellite, n=len(x), Pearson_r=r, Pearson_p=p))    axes[0].set_ylabel('Orbital decay (m/day)\nPositive = altitude loss')    fig.suptitle('Geomagnetic Activity and Daily Orbital Decay',                 fontsize=21, fontweight='bold')    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)    for extension in ['png', 'pdf']:        destination = OUTPUT_DIR / f'Kp_vs_orbital_decay.{extension}'        fig.savefig(destination, dpi=400, bbox_inches='tight')        print('Saved:', destination)    stats = pd.DataFrame(results)    stats.to_csv(OUTPUT_DIR / 'Kp_decay_correlations.csv', index=False)    data.to_csv(OUTPUT_DIR / 'Kp_decay_plotted_observations.csv', index=False)    print('\n', stats.to_string(index=False))    print('\nStatistics use exactly the plotted observations. Standard Pearson p values '          'do not adjust for dependence between successive days. Compare the methods '          'with your existing analysis before replacing poster statistics.')    plt.show()if __name__ == '__main__':    main()